SELECT DATE_FORMAT(stat_date, '%Y-%m-%d') AS date, COALESCE(SUM(contract_count), 0) AS count, COALESCE(SUM(total_amount), 0) AS amount FROM custom_contract_daily_stats WHERE stat_date BETWEEN #{from} AND #{to}
AND tenant_id = #{tenantId}
AND status NOT IN #{s}
GROUP BY stat_date ORDER BY stat_date

SELECT
    DATE_FORMAT(create_time, '%Y-%m-%d') AS date,
    COUNT(*)                             AS count,
    COALESCE(SUM(salary), 0)             AS amount
FROM custom_contract
WHERE create_time >= #{fromInclusive}
  AND create_time < #{toExclusive}

    AND tenant_id = #{tenantId}


    AND COALESCE(status, 0) NOT IN
    #{s}

GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY date
